function validate([queens, king]) {
  if (!Array.isArray(queens) || queens.length < 1 || queens.length > 63) return 'queens needs 1 to 63 positions.';
  const onBoard = p => Array.isArray(p) && p.length === 2 && p.every(v => Number.isInteger(v) && v >= 0 && v < 8);
  if (!onBoard(king)) return 'king must be [x, y] with both values from 0 to 7.';
  if (!queens.every(onBoard)) return 'Each queen must be [x, y] with both values from 0 to 7.';
  const seen = new Set([king[0] * 8 + king[1]]);
  for (const [x, y] of queens) {
    if (seen.has(x * 8 + y)) return 'Every queen and the king need their own square.';
    seen.add(x * 8 + y);
  }
  return null;
}

