function queensAttacktheKing(queens, king) {
  const [kx, ky] = king;
  const result = [];
  for (const [qx, qy] of queens) {
    const dx = qx - kx;
    const dy = qy - ky;
    if (dx !== 0 && dy !== 0 && Math.abs(dx) !== Math.abs(dy)) continue;
    const steps = Math.max(Math.abs(dx), Math.abs(dy));
    let blocked = false;
    for (let s = 1; s < steps; s++) {
      const x = kx + Math.sign(dx) * s;
      const y = ky + Math.sign(dy) * s;
      if (queens.some(([ox, oy]) => ox === x && oy === y)) blocked = true;
    }
    if (!blocked) result.push([qx, qy]);
  }
  return result;
}

