function generate(rand, size) {
  const cells = Array.from({ length: 64 }, (_, i) => i);
  for (let i = cells.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [cells[i], cells[j]] = [cells[j], cells[i]];
  }
  const count = size === 'large' ? 40 + Math.floor(rand() * 24) : 1 + Math.floor(rand() * 14);
  const king = [Math.floor(cells[0] / 8), cells[0] % 8];
  const queens = cells.slice(1, 1 + count).map(c => [Math.floor(c / 8), c % 8]);
  return [queens, king];
}
